function uiSubjectIcon(string $name): string {
    $name = mb_strtolower($name);
    foreach (['matematika'=>'math','fisika'=>'flask','pemrograman'=>'code','tik'=>'code','inggris'=>'translate','biologi'=>'microscope','indonesia'=>'book'] as $word=>$icon) {
        if (str_contains($name,$word)) return $icon;
    }
    return 'book';
}
function uiQuery(array $changes = [], string $path = ''): string {
    $params = array_merge($_GET,$changes);
    return e($path . '?' . http_build_query(array_filter($params,fn($value) => $value !== null && $value !== '')));
}
function uiDisplayText(?string $text): string {
    return trim(str_replace('[EDULMS-DEMO-V1]','',$text??''));
}
function uiSubjectGlyph(string $name, ?string $stored = null, int $size = 20): string {
    $allowed=['math','book','flask','terminal','translate','microscope','school'];
    $icon=in_array($stored,$allowed,true)?$stored:uiSubjectIcon($name);
    return uiIcon(match($icon){'code'=>'terminal','book'=>'book-auto',default=>$icon},$size);
}
function uiPaginate(array $items,int $perPage=5,string $parameter='page'): array {
    $total=count($items);$pages=max(1,(int)ceil($total/$perPage));
    $page=min($pages,max(1,(int)($_GET[$parameter]??1)));
    return ['items'=>array_slice($items,($page-1)*$perPage,$perPage),'page'=>$page,'pages'=>$pages,'total'=>$total];
}
function uiPagination(int $page,int $pages,int $total,string $label,string $parameter='page',array $changes=[]): void {
    if($pages<=1)return;
    echo '<div class="ui-pagination"><span>'.e($total.' '.$label.' / Halaman '.$page.' dari '.$pages).'</span><nav aria-label="Halaman '.e($label).'">';
    if($page>1)echo '<a class="page-previous" href="'.uiQuery(array_merge($changes,[$parameter=>$page-1])).'">'.uiIcon('chevron-left',16).'<span>Sebelumnya</span></a>';
    else echo '<span aria-disabled="true">Sebelumnya</span>';
    for($number=1;$number<=$pages;$number++){
        if($number===$page)echo '<span class="active" aria-current="page">'.$number.'</span>';
        else echo '<a href="'.uiQuery(array_merge($changes,[$parameter=>$number])).'" aria-label="Halaman '.$number.'">'.$number.'</a>';
    }
    if($page<$pages)echo '<a class="page-next" href="'.uiQuery(array_merge($changes,[$parameter=>$page+1])).'"><span>Selanjutnya</span>'.uiIcon('chevron-right',16).'</a>';
    else echo '<span aria-disabled="true">Selanjutnya</span>';
    echo '</nav></div>';
}
function uiShortDate(string $date, bool $time = false): string {
    $stamp = strtotime($date);
    $day = date('Y-m-d',$stamp);
    $delta=(int)round((strtotime(date('Y-m-d'))-strtotime($day))/86400);
    $label=match(true){$delta===0=>'Hari ini',$delta===-1=>'Besok',$delta===1=>'Kemarin',$delta>=2&&$delta<=7=>$delta.' hari yang lalu',default=>formatTanggalIndo($date)};
    return $label . ($time ? ', '.date('H:i',$stamp).' WIB' : '');
}
function uiYear(): string { return defined('TAHUN_AJARAN_AKTIF') ? TAHUN_AJARAN_AKTIF : '2026/2027'; }
function uiFullDate(string $date): string {
    $stamp=strtotime($date);
    $days=['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
    $months=[1=>'Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
    return $days[(int)date('w',$stamp)].', '.date('j',$stamp).' '.$months[(int)date('n',$stamp)].' '.date('Y',$stamp);
}
function uiEmpty(string $title, string $text = ''): void {
    echo '<div class="ui-empty">'.uiIcon('book',32).'<h3>'.e($title).'</h3><p>'.e($text).'</p></div>';
}

function uiClassCover(string $subject, string $class): string {
    $physics = uiSubjectIcon($subject) === 'flask';
    if ($physics) return str_starts_with($class, 'XI ') ? 'class-physics-1.png' : 'class-physics-2.png';
    if (!str_starts_with($class, 'XI ')) return 'class-math-3.png';
    return str_ends_with($class, '2') ? 'class-math-2.png' : 'class-math-1.png';
}

function uiAvatar(string $name, ?string $path): string {
    $assetRoot=realpath(__DIR__.'/../assets/images');
    $real=$path ? realpath(__DIR__.'/../'.$path) : false;
    if ($real && $assetRoot && str_starts_with($real,$assetRoot.DIRECTORY_SEPARATOR) && preg_match('/\.(png|jpe?g|webp)$/i',$real)) {
        return '<img class="student-initial" src="'.e('../'.str_replace('\\','/',$path)).'" alt="">';
    }
    return '<span class="student-initial" aria-hidden="true">'.e(mb_substr($name,0,1)).'</span>';
}
